/// [정통사주 69종 개인화 해석 엔진 — A01/A03 100명 이상 검증] 확장 표본.
///
/// 사용자 최종 지시 "A01/A03 100명 검증" 섹션 1에 대응한다. 기존
/// `jeontong_sample_30.dart`(30명)는 그대로 유지하고(삭제/변경 금지 —
/// 기존 테스트가 참조 중), 별도 파일로 120명 표본을 새로 만든다.
///
/// [분산 설계] 아래 항목이 가능한 한 고르게 섞이도록 생년월일시·성별을
/// 결정론적 공식으로 생성한다(랜덤 시드/해시 사용 금지 — 사용자 지시
/// "해시/랜덤 seed로 명식 생성 금지"에 따라, 매 실행마다 완전히 동일한
/// 120개 값이 나오는 고정 리스트를 코드로 "생성"만 하고 저장한다):
///   - 성별: 홀짝 인덱스로 M/F 교차
///   - 출생년도: 1950~2015년 사이, 66년 폭을 120개로 촘촘히 분산
///   - 월: 1~12월을 다른 보폭(step)으로 순환시켜 연도와 겹치지 않게 분산
///   - 일: 1~28일을 또 다른 보폭으로 순환
///   - 시: 0~23시를 또 다른 보폭으로 순환(자시/야자시 경계 포함)
///
/// 이렇게 하면 일간(day gan) 60갑자가 실질적으로 넓게 분포하고, 그 결과
/// 신강/신약/중화, 재성 강약, 오행 편중 등도 자연히 다양해진다(사주
/// 계산값을 인위로 맞추는 것이 아니라 "입력 자체를 다양하게" 만드는
/// 방식 — PHASE1~4는 그 다양한 입력을 있는 그대로 계산할 뿐이다).
library;

import 'jeontong_inputs.dart';

DateTime _dt(int y, int m, int d, int h) => DateTime.utc(y, m, d, h, 0, 0);

/// 120명 결정론적 생성 표본. 최소 100명 이상 요구(사용자 지시)를
/// 여유 있게 만족시킨다.
final List<JeontongInput> kJeontongSample120 = List<JeontongInput>.generate(
  120,
  (i) {
    // i: 0~119
    //
    // [2026 수정 — 다양성 검증 실패로 인한 보정] 최초 버전은
    // step(11,5,7,3)과 각 폭(66,12,28,24)의 최대공약수가 1이 아니어서
    // (year 주기=6, month 주기=12, day 주기=4, hour 주기=8 → 전체 주기
    // lcm=24)에 걸려, 120명 중 실제로는 24가지 (년,월,일,시) 조합만
    // 반복 등장했다(검증 테스트 `fixture_diversity_120_test.dart`가
    // 이를 실측으로 적발). 각 step을 해당 폭과 서로소로 재선정해
    // 결합 주기(lcm)가 120을 훨씬 넘도록 고친다 — 계산 로직이 아니라
    // "입력 분산 공식"만 조정한 것이며 PHASE1~4는 무관하다.
    //   year : step=13, 폭=66 → gcd(13,66)=1 → 주기 66
    //   month: step=7,  폭=12 → gcd(7,12)=1  → 주기 12
    //   day  : step=13, 폭=28 → gcd(13,28)=1 → 주기 28
    //   hour : step=17, 폭=24 → gcd(17,24)=1 → 주기 24
    //   전체 결합 주기 = lcm(66,12,28,24) = 1848 (≫120) → 120명 전원
    //   서로 다른 (년,월,일,시) 조합이 보장된다.
    final year = 1950 + (i * 13) % 66; // 1950~2015 사이를 넓게 순회
    final month = 1 + (i * 7) % 12; // 1~12월
    final day = 1 + (i * 13) % 28; // 1~28일
    final hour = (i * 17) % 24; // 0~23시(0시 야자시 포함)
    final gender = i.isEven ? 'M' : 'F';
    return JeontongInput(
      userId: 'p120-${(i + 1).toString().padLeft(3, '0')}',
      birthDateTimeUtc: _dt(year, month, day, hour),
      isLunar: false,
      gender: gender,
    );
  },
  growable: false,
);
